#!/usr/bin/perl
use strict; use warnings;
use File::Find;
use File::Basename;

my @allgo;
find(sub { push @allgo, $File::Find::name if /\.go$/ && $File::Find::name !~ m{/\.git/} }, '.');

my (@decls, %pkgname);
for my $p (@allgo) {
    next unless $p =~ m{^\./internal/};
    next if $p =~ /_test\.go$/;
    open my $fh, '<', $p or next;
    my $ln = 0;
    my $dir = dirname($p);
    while (my $line = <$fh>) {
        $ln++;
        if ($line =~ /^package\s+(\S+)/) { $pkgname{$dir} = $1 unless exists $pkgname{$dir}; }
        if ($line =~ /^func\s+(?:\(([^)]*)\)\s+)?([A-Za-z_0-9]+)\s*\(/) {
            push @decls, { name => $2, recv => (defined $1 ? 1 : 0), path => $p, line => $ln, dir => $dir };
        }
    }
    close $fh;
}

my %cache;
sub lines_of {
    my $p = shift;
    unless (exists $cache{$p}) {
        open my $fh, '<', $p or return [];
        local $/; my $c = <$fh>; close $fh;
        $cache{$p} = [split /\n/, $c];
    }
    return $cache{$p};
}

my @results;
for my $d (@decls) {
    my $name = $d->{name};
    my ($pat, @scope);
    if ($d->{recv}) {
        $pat = qr/\.\Q$name\E\s*\(/;
        @scope = @allgo;
    } elsif ($name =~ /^[A-Z]/) {
        my $pk = $pkgname{$d->{dir}} // '';
        $pat = qr/\b\Q$pk\E\.\Q$name\E\s*\(/;
        @scope = @allgo;
    } else {
        $pat = qr/(?<![A-Za-z_0-9.])\Q$name\E\s*\(/;
        @scope = grep { dirname($_) eq $d->{dir} } @allgo;
    }
    my ($prod, $test) = (0, 0);
    my %byfile;
    for my $p (@scope) {
        my $lines = lines_of($p);
        for my $l (@$lines) {
            next if $l =~ /^func\s/;
            if ($l =~ $pat) {
                if ($p =~ /_test\.go$/) { $test++ } else { $prod++; $byfile{$p}++ }
            }
        }
    }
    push @results, { prod => $prod, test => $test, %$d, byfile => \%byfile };
}

@results = sort { $b->{prod} <=> $a->{prod} } @results;
for my $r (@results[0..24]) {
    last unless $r;
    printf "%d (+%d test) %s %s:%d %s\n", $r->{prod}, $r->{test}, $r->{name}, $r->{path}, $r->{line}, ($r->{recv} ? 'method' : 'func');
    my $bf = $r->{byfile};
    my @f = sort { $bf->{$b} <=> $bf->{$a} } keys %$bf;
    for my $f (@f[0..4]) { last unless $f; printf "        %d %s\n", $bf->{$f}, $f; }
}

